SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;


-- Weapon data from weapons.csv

DECLARE @ComponentId INT;

IF NOT EXISTS (SELECT 1 FROM Erkul.Manufacturer WHERE ManufacturerName = N'Vanduul')
    INSERT INTO Erkul.Manufacturer (ManufacturerName, ManufacturerCode) VALUES (N'Vanduul', N'VNCL');
IF NOT EXISTS (
    SELECT 1
    FROM Erkul.Component c
    INNER JOIN Erkul.Manufacturer m ON m.ManufacturerId = c.ManufacturerId
    INNER JOIN Erkul.ComponentCategory cat ON cat.CategoryId = c.CategoryId
    WHERE c.ComponentName = N'"WAR"' AND m.ManufacturerName = N'Vanduul' AND cat.CategoryName = N'Weapon'
    AND ISNULL(c.Size, -1) = ISNULL(5, -1)
    AND ISNULL(c.Class, N'') = ISNULL(NULL, N'')
    AND ISNULL(c.Grade, N'') = ISNULL(NULL, N'')
    AND ISNULL(c.WeaponType, N'') = ISNULL(N'Laser Cannon', N'')
    AND ISNULL(c.TrackingSignalType, N'') = ISNULL(NULL, N'')
)
BEGIN
    INSERT INTO Erkul.Component
    (
        ComponentName, ManufacturerId, CategoryId, Size, Class, Grade, WeaponType, TrackingSignalType,
        Health, Price, DistortionShutdownDmg, DistortionDecayDelay, DistortionDecayRate, DistortionRecoveryRatio, DistortionWarningRatio,
        SourceFile, SourceRowNumber
    )
    SELECT
        N'"WAR"',
        m.ManufacturerId,
        cat.CategoryId,
        5,
        NULL,
        NULL,
        N'Laser Cannon',
        NULL,
        2640,
        NULL,
        500000,
        0,
        500000,
        0,
        0.75,
        N'weapons.csv',
        2
    FROM Erkul.Manufacturer m
    CROSS JOIN Erkul.ComponentCategory cat
    WHERE m.ManufacturerName = N'Vanduul'
      AND cat.CategoryName = N'Weapon';
END;
SELECT @ComponentId = c.ComponentId
FROM Erkul.Component c
INNER JOIN Erkul.Manufacturer m ON m.ManufacturerId = c.ManufacturerId
INNER JOIN Erkul.ComponentCategory cat ON cat.CategoryId = c.CategoryId
WHERE c.ComponentName = N'"WAR"' AND m.ManufacturerName = N'Vanduul' AND cat.CategoryName = N'Weapon'
    AND ISNULL(c.Size, -1) = ISNULL(5, -1)
    AND ISNULL(c.Class, N'') = ISNULL(NULL, N'')
    AND ISNULL(c.Grade, N'') = ISNULL(NULL, N'')
    AND ISNULL(c.WeaponType, N'') = ISNULL(N'Laser Cannon', N'')
    AND ISNULL(c.TrackingSignalType, N'') = ISNULL(NULL, N'');
IF NOT EXISTS (SELECT 1 FROM Erkul.Weapon WHERE ComponentId = @ComponentId)
    INSERT INTO Erkul.Weapon (ComponentId, BurstDPS, PenetrationDistance, PenetrationNearRadius, PenetrationFarRadius, PowerConsumption, MaxAmmos, AmmosRegen, Overheat, FireRate, TotalDamageDealt, TotalDealtTime, FullChargeFireRate, WeaponRange, Speed, ChargeTime, FireOnlyOnFullCharge, FireAutomaticallyOnFullCharge, PelletsPerShot, RegenCooldown, SpreadFirstAttack, SpreadAttack, SpreadMin, SpreadMax, SpreadDecay) VALUES (@ComponentId, 945, 2.4, 0.1, 0.2, 1.4, 25, NULL, NULL, 100, NULL, NULL, NULL, 3478, 1288, NULL, NULL, NULL, 0, 0.49, 0.025, 0.025, 0.45, 0.45, 0.05);
IF NOT EXISTS (SELECT 1 FROM Erkul.DamageProfile WHERE ComponentId = @ComponentId)
    INSERT INTO Erkul.DamageProfile (ComponentId, DamageTotal, DamageBiochemical, DamageDistortion, DamageEnergy, DamagePhysical, DamageStun, DamageThermal, AlphaMin, AlphaMax, ChargedDamageMultiplier, ExplosionRadius, ExplosionRadiusMin, ExplosionRadiusMax) VALUES (@ComponentId, NULL, 0, 0, 0, 0, 0, 0, 567, 567, NULL, NULL, NULL, NULL);


