    INSERT INTO Erkul.Manufacturer (ManufacturerName, ManufacturerCode) VALUES (N'ACOM', N'ACOM');
IF NOT EXISTS (
    SELECT 1
    FROM Erkul.Component c
    INNER JOIN Erkul.Manufacturer m ON m.ManufacturerId = c.ManufacturerId
    INNER JOIN Erkul.ComponentCategory cat ON cat.CategoryId = c.CategoryId
    WHERE c.ComponentName = N'StarBurn' AND m.ManufacturerName = N'ACOM' AND cat.CategoryName = N'Power Plant'
    AND ISNULL(c.Size, -1) = ISNULL(2, -1)
    AND ISNULL(c.Class, N'') = ISNULL(N'Competition', N'')
    AND ISNULL(c.Grade, N'') = ISNULL(N'B', N'')
